	(140, 'ffb54f0b-fbe8-4ab4-9d60-2974dce75dc5', 'lounge_goal', 1, 'GoalPlaced', '{"x": 0, "y": 32, "z": 0, "kind": "finish", "width": 5, "facing": 0, "height": 3, "worldId": "ab66017f-aa48-42ce-8197-2c57237e0e27"}', '{"actorId": "7d7a7be4-d826-4b3f-b1df-9e4fd6b8f21c", "correlationId": "de266c23-74bd-47fc-9c96-112689b8fd5b"}', '7d7a7be4-d826-4b3f-b1df-9e4fd6b8f21c', '2026-11-27 15:04:27.579164+00', '7f433e67-9785-4e08-b534-ecfeedc517f7', 140);
INSERT INTO "public"."feature_flags" ("key", "enabled", "label", "description", "updated_at", "value_int") VALUES
	('billing', true, 'Billing', 'Off means no subscription is required: workspaces stay writable and anyone can create one. Override off for a single user or workspace to comp them.', '2026-11-27 15:03:10.560498+00', NULL),
	('pages', true, 'Pages', 'The documents surface at /t/[slug]/pages.', '2026-11-27 15:03:10.560498+00', NULL),
	('lounge', true, 'Lounge', 'The multiplayer 3D lounge.', '2026-11-27 15:03:10.560498+00', NULL),
	('cafe', true, 'Café and world', 'The café and the house and garden the travel bar leads to.', '2026-11-27 15:03:10.560498+00', NULL),
	('agents', false, 'Creatures', 'Self-directed animals that live in the café, house, garden and lounge, and decide for themselves whether to wander, sit or sleep.', '2026-11-27 15:03:10.622653+00', NULL),
	('open_registration', true, 'Open registration', 'On means anybody can create an account. Off means sign-up is by invitation only, and everyone else lands on the waiting list at /waitlist. Invitations work either way.', '2026-11-27 15:03:10.836391+00', NULL),
	('seat_limit', false, 'Seat limit per space', 'Off means a space may hold any number of people. On caps members plus pending invitations at the number, for every space at once. Override it for one space to give that space a different cap.', '2026-11-27 15:03:10.836391+00', 12),
	('guest_limit', false, 'Guests in a space at once', 'Off means any number of guests may be in a space at the same time. On caps how many are inside simultaneously, for every space at once. Override it for one space to give that space a different cap. This is separate from a link''s own use limit.', '2026-11-27 15:03:10.925517+00', 8),
	('radio', false, 'Space radio', 'An owner or admin can put a SoundCloud track on, and everybody in the space hears it from the same place.', '2026-11-27 15:03:11.231704+00', NULL),
	('tasks', false, 'Tasks', 'The per-space task list and its tab. Off by default - withdrawn in favour of task lists inside pages. Turning it on for a space restores its existing list untouched.', '2026-11-27 15:03:11.490083+00', NULL),
	('xp_sales', false, 'xp tier on sale', 'Whether the €10 xp plan can be bought. Off means xo is the only plan on sale and xp shows as coming soon; spaces that already hold xp by voucher or grandfathering keep it either way. Turning this on is the xp launch.', '2026-11-27 15:03:11.65418+00', NULL),
	('renders', false, 'Scene renders', 'A scene can be turned into an image by a worker instead of by the browser that composed it: the request is registered as a job, a headless renderer draws it, and the picture lands in Storage. Any caller can ask - the board, the scene catalogue, a space, a script.', '2026-11-27 15:03:11.72077+00', NULL),
	('xo_place_limit', false, 'Rooms per space', 'Off means a space may hold any number of rooms. On caps rooms that are not levels, for every space at once. The tier already sets this per space - use this only as a platform ceiling, and override one space to raise it.', '2026-11-27 15:03:12.682829+00', 30),
	('xp_place_limit', false, 'XP places per space', 'Off means no cap. On caps rooms that are levels, for every space at once. The tier already sets this per space; this is the ceiling above it.', '2026-11-27 15:03:12.682829+00', 10),
	('project_limit', false, 'XP projects per space', 'Off means no cap. On caps the XPs a space may edit. The tier already sets this per space; this is the ceiling above it.', '2026-11-27 15:03:12.682829+00', 20),
	('match_limit', false, 'Matches at once per space', 'Off means no cap. On caps how many battles a space may have open at the same time. Concurrency, never a monthly allowance.', '2026-11-27 15:03:12.682829+00', 30),
	('free_space_limit', false, 'Free spaces one account may own', 'Off means no cap. On caps how many spaces one account may own without paying for them. Owning paid spaces is never capped - a subscription is per space. Being a member of other people''s spaces is never capped either. Override it for one account to let somebody hold more.', '2026-11-27 15:03:12.682829+00', 10),
	('page_limit', false, 'Pages per space', 'Off means a space may hold any number of pages. On caps them for every space at once. The tier already sets this per space; this is the ceiling above it.', '2026-11-27 15:03:12.689811+00', 100),
	('picture_limit', false, 'Uploaded images per space', 'Off means no cap on how many images a space may hold. On caps them for every space at once. Uploaded images only - the pictures that ship with the product are a platform catalogue and cost a space nothing.', '2026-11-27 15:03:12.689811+00', 100),
	('perf', false, 'Room performance', 'Off, nothing in a lounge or battle room measures anything. On, every client in every space samples its own channel, frame rate and round trip and writes them for /ovaloffice/performance - about 5% extra traffic on a busy room''s channel. Add a tenant override to narrow it to one space. Whether players are shown their own readings is a separate per-space switch in Space Settings, not this. Samples already written stay readable when this goes off.', '2026-11-27 15:03:12.83836+00', NULL),
	('chat', true, 'Lounge chat', 'A text channel in the lounge, alongside the emotes. On by default; each space can switch its own off in Space Settings.', '2026-11-27 15:03:12.890024+00', NULL),
	('mobile_api', false, 'Mobile API', 'Whether this space may be used through the native app''s API (/api/m). Off, every space-scoped route answers "blocked" before it reads anything; the account''s own routes - profile, the list of spaces - keep working, so the app can still say who you are and show the shelf. Switch a space on with a tenant override.', '2026-11-27 15:03:13.719764+00', NULL),
	('battle', true, 'Battle system', 'Saved battlefields, matches (all-vs-all, teams, one-vs-everyone), challenges between spaces, and tournaments.', '2026-11-27 15:03:10.687859+00', NULL),
	('worlds', true, 'World catalogue', 'A space can build worlds in the block builder, publish them, and pull worlds other spaces have published into a battlefield of its own.', '2026-11-27 15:03:11.279032+00', NULL),
	('scenes', true, 'Scenes', 'A space can save scenes from the motion studio and pin them to its board, where they play in place.', '2026-11-27 15:03:11.325667+00', NULL),
	('economy', false, 'The coin economy', 'Off, nothing charges anybody and nothing pays out: battles are free to enter and pay nothing, doors take no toll, needs cost nothing, and a quota is whatever the tier says with no way to buy past it. Coins already in a purse stay there and the cafe keeps paying them - that predates all of this and switching the economy off must not take somebody''s savings with it. On, the rules in docs/product/economy.md apply. Add a tenant override to switch one space on; that is the intended way in.', '2026-11-27 15:03:13.733548+00', NULL),
	('private_xp_limit', false, 'Private XPs per space', 'Off means no cap. On caps the XPs a space may keep private - visible only to their owner and whoever they named. The tier already sets this per space; this is the ceiling above it. Free holds none of these at all and no amount of coins buys one, so this flag cannot loosen free - only an override on the space can.', '2026-11-27 15:03:13.733548+00', 100),
	('public_xp_limit', false, 'Published XPs per space', 'Off means no cap. On caps the XPs a space may have published in the catalogue. The tier already sets this per space; this is the ceiling above it. Beyond the tier''s allowance a member may buy one more with coins, which is what this ceiling stands above.', '2026-11-27 15:03:13.733548+00', 100),
	('blueprint_limit', false, 'Blueprints per space', 'Off means no cap. On caps the blueprints in a space''s workshop. Vehicles are counted separately and are not affected. The tier already sets this per space; this is the ceiling above it.', '2026-11-27 15:03:13.733548+00', 100),
	('clip_limit', false, 'Clips per space', 'Off means no cap. On caps the animator clips a space has saved. The tier already sets this per space; this is the ceiling above it.', '2026-11-27 15:03:13.733548+00', 100),
	('vehicle_limit', false, 'Vehicles per space', 'Off means the tier decides, and every tier includes none - so off means every vehicle is bought with coins, at a price that differs by tier. Switching this on and setting a number is a comp: it hands a space vehicles it did not pay for. That is a legitimate thing to do for a partner, a demo or an event, and it is not the same gesture as the other limits here, which only lift what somebody already bought.', '2026-11-27 15:03:13.733548+00', 10),
	('voucher', false, 'Vouchers', 'Off, there are no vouchers and a player with an empty purse earns their way back through the cafe. On, somebody with nothing left may claim one, once per space, worth whatever this value says. The number matters more than the switch: 10000 is a hundred times the opening balance, so a voucher that size flattens every price in the product for as long as it lasts. Lower it for a space running an economy; leave it for a space running an event.', '2026-11-27 15:03:13.902998+00', 10000),
	('xo_universe', true, 'XO Universe', 'The Project Oasis channel and its nav tab. Off takes the tab away and 404s the routes; the chapters and their published rows are untouched, so turning it back on restores the channel exactly as the editors left it.', '2026-11-27 15:03:13.943009+00', NULL),
	('channels', false, 'Channels', 'Member-written shows: the editor inside a space, the review queue in the backoffice, and the public directory at /xo-universe/channels. Off takes all three away and leaves already-released episodes unreachable rather than deleted.', '2026-11-27 15:03:14.008959+00', NULL),
	('xoin', false, 'Xoin market', 'A market with one thing in it: the cartridge, and the space''s own book behind it. What a trade costs depends on the mode the space chose - play money by default.', '2026-11-27 15:03:14.324292+00', NULL),
	('xp', true, 'XP', 'A space can fight a match inside an XP: its own level with its own rules, played in the battle room, with everybody who joins in one room and able to see each other move. No score comes back out of an XP yet.', '2026-11-27 15:03:11.592838+00', NULL),
	('pictures', true, 'Image uploads', 'Off means nobody may upload an image, and the surface offering it is gone. Images already stored keep being served - this switch withholds the feature, it does not unpublish anything. On restores uploading, still subject to the per-space image limit.', '2026-11-27 15:03:12.689811+00', NULL),
	('faces', true, 'Faces in the lounge', 'People in a world may switch on their camera, and wear it as a face over their body. The picture goes directly from one browser to another and is never stored.', '2026-11-27 15:03:13.053429+00', NULL),
	('skin_shop', true, 'Skin shop', 'The shelf of character skins for the XP body: regular skins for money, super skins for vouchers. Owned skins keep working when this is off; what closes is buying.', '2026-11-27 15:03:13.383931+00', NULL),
	('thingiverse', true, 'Thingiverse', 'A shelf of object blueprints a space can summon into its rooms: a model out of the packs, with its own size, whether it blocks the way and whether it falls. Off, the rail tab and the /thingiverse command are gone and nothing is drawn from the shelf. Things already summoned are kept and reappear when this goes back on.', '2026-11-27 15:03:13.536779+00', NULL);
