INSERT INTO "public"."profile_avatars" ("user_id", "model", "updated_at", "show_xp") VALUES
	('7d7a7be4-d826-4b3f-b1df-9e4fd6b8f21c', 'pig', '2026-11-27 15:09:14.412+00', false);
INSERT INTO "public"."skins" ("id", "name", "tier", "price_cents", "voucher_cost", "backstory", "active", "created_at", "updated_at", "variant_of") VALUES
	('adventurers/Knight', 'Sir Percival', 'skin', 300, 1, 'Percival treats every lobby as a castle and every guest as visiting royalty. Holds the door, holds the line, holds the high score on exactly one machine and will not say which. The armour has never once been off; the leaderboards suggest neither has he.', true, '2026-11-27 15:03:13.383931+00', '2026-11-27 15:03:13.383931+00', NULL),
	('adventurers/Barbarian', 'Bram', 'skin', 300, 1, 'Bram is the loud half of the arcade in one person. Celebrates wins by roaring, celebrates losses by roaring, orders a lemonade at the café by roaring, quietly. The axe is foam. The enthusiasm is not.', true, '2026-11-27 15:03:13.383931+00', '2026-11-27 15:03:13.383931+00', NULL),
	('adventurers/Druid', 'Moss', 'skin', 300, 1, 'Moss speaks for the potted plants, and claims they have opinions about the music. Turned the corner of the lounge into a small forest nobody remembers agreeing to and nobody would now give up. If you are lost, Moss is the one the birds ask.', true, '2026-11-27 15:03:13.383931+00', '2026-11-27 15:03:13.383931+00', NULL),
	('adventurers/Engineer', 'Sprocket', 'skin', 300, 1, 'Sprocket built half the cabinets in the arcade and fixed the other half after Bram. Carries a wrench the way other people carry opinions, and has never met a machine that stayed broken out of spite. The goggles are for welding. The grin is standard issue.', true, '2026-11-27 15:03:13.383931+00', '2026-11-27 15:03:13.383931+00', NULL),
	('adventurers/Ranger', 'Fletch', 'skin', 300, 1, 'Fletch has never missed. Not the target, not the last train, not a single word of gossip whispered across the lounge. Stands at the back of every photo and somehow ends up in focus. The quiver is full; nobody has ever seen an arrow leave it.', true, '2026-11-27 15:03:13.383931+00', '2026-11-27 15:03:13.383931+00', NULL),
	('adventurers/Rogue', 'Sly', 'skin', 300, 1, 'Sly wins card games nobody remembers agreeing to play. The coins on the table are yours, briefly. Utterly trustworthy in every matter except games of chance, directions, and the question of who ate the last slice.', true, '2026-11-27 15:03:13.383931+00', '2026-11-27 15:03:13.383931+00', NULL),
	('adventurers/Mage', 'Vex', 'super', 0, 2, 'Vex once beat a level by arguing with its physics until the physics apologised. The robes crackle faintly near vending machines, which now dispense for free and are afraid to say so. Do not ask about the hat. The hat is load-bearing.', true, '2026-11-27 15:03:13.383931+00', '2026-11-27 15:03:13.383931+00', NULL),
	('adventurers/Rogue_Hooded', 'The Hood', 'super', 0, 2, 'Nobody has seen the face under the hood, and the hood has seen everything. Appears on the leaderboard as three different names, all first. Leaves before the applause, tips the café generously, and is rumoured to be someone you know.', true, '2026-11-27 15:03:13.383931+00', '2026-11-27 15:03:13.383931+00', NULL),
	('kappa/Monster', 'Gnash', 'skin', 0, 0, 'Gnash lives under the arcade and comes up for the noise. Has never won a game and never stopped grinning about it; the teeth are for smiling, mostly. Free to wear, because Gnash believes doors, tickets and prices are things that happen to other people.', true, '2026-11-27 15:03:13.471144+00', '2026-11-27 15:03:13.471144+00', NULL),
	('kappa/MonsterCostume', 'Definitely Gnash', 'skin', 0, 0, 'Absolutely, certainly the real monster and not somebody in a zip-up suit who heard the real one gets free lemonade. The tail drags a little. The roar needs work. The confidence is one hundred percent genuine, and that is what counts.', true, '2026-11-27 15:03:13.471144+00', '2026-11-27 15:03:13.471144+00', NULL),
	('adventurers/Barbarian_Large', 'Big Bram', 'super', 0, 2, 'Every legend gets taller with each telling; Big Bram is what happens when the telling goes on all night. Twice the Bram, twice the roar, ducks through doorways as a courtesy to the doorways. The ground does not shake - it applauds.', false, '2026-11-27 15:03:13.383931+00', '2026-11-27 15:03:13.49102+00', NULL),
	('spacenina/CombatMech', 'Rustbucket', 'skin', 300, 1, 'Rustbucket was built for a war that never came and has spent every year since being extremely helpful instead. Carries the shopping, reaches the top shelf, wins at every game involving a hammer. The armour plating is decorative. The politeness is factory-fitted, and nobody has found the switch.', true, '2026-11-27 15:03:14.291259+00', '2026-11-27 15:03:14.291259+00', NULL),
	('spacenina/CombatMech_Olive', 'Rustbucket in olive', 'skin', 0, 0, 'The same Rustbucket in field paint, which it repainted itself one weekend and has never explained.', true, '2026-11-27 15:03:14.29366+00', '2026-11-27 15:03:14.29366+00', 'spacenina/CombatMech');
